using System;using System.Linq;using System.Collections.Generic;using System.Windows.Media.Media3D;
namespace GearLab {
 public static class TransmissionAudit {
  public static List<string> BroadPhase(Result r,double phase=0){var warnings=new List<string>();var parts=r.Model.Parts.Where(p=>!p.Reference).ToArray();var boxes=new Dictionary<string,double[]>();foreach(var part in parts){var m=part.Placement*PartMotion.Bind(r,part).At(phase,0);var a=new CadAssembly();var q=new CadPart(part.Id,part.Label,part.Role,part.Color){Placement=m,MeshOverride=part.MeshOverride};q.Sections.AddRange(part.Sections);a.Parts.Add(q);boxes[part.Id]=a.Bounds();}for(int i=0;i<parts.Length;i++)for(int j=i+1;j<parts.Length;j++){if(r.Train!=null){string stage1=parts[i].Id.Split('_')[0],stage2=parts[j].Id.Split('_')[0];if(stage1==stage2)continue;}var a=boxes[parts[i].Id];var b=boxes[parts[j].Id];if(Math.Min(a[1],b[1])-Math.Max(a[0],b[0])>.1&&Math.Min(a[3],b[3])-Math.Max(a[2],b[2])>.1&&Math.Min(a[5],b[5])-Math.Max(a[4],b[4])>.1){warnings.Add(parts[i].Label+" ↔ "+parts[j].Label);if(warnings.Count>=100)return warnings;}}return warnings;}
  public static double[] BearingReactions(double force,double loadZ,double bearing1,double bearing2){if(bearing2<=bearing1)throw new ArgumentException("Опоры должны иметь разные положения.");double r2=force*(loadZ-bearing1)/(bearing2-bearing1);return new[]{force-r2,r2};}
  public static void BearingLoads(Result r,CadAssembly model){if(r.Engineering==null||r.P.Kind==11||r.Engineering.MultiInput)return;var p=r.P;double inputF=Math.Sqrt(r.Engineering.Tangential*r.Engineering.Tangential+r.Engineering.Radial*r.Engineering.Radial);double outputFt=p.Kind==12?r.Engineering.OutputForce:2000*r.Engineering.OutputTorque/Math.Max(1,p.Module*Math.Max(r.Z2,r.Z1)),outputF=Math.Sqrt(outputFt*outputFt+r.Engineering.OutputRadial*r.Engineering.OutputRadial);foreach(string id in new[]{"IN","OUT"}){var b=model.Parts.Where(q=>q.Id.StartsWith("H_BEARING_"+id)).ToArray();if(b.Length!=2)continue;double z1=(b[0].Sections[0].Bottom+b[0].Sections[0].Top)/2,z2=(b[1].Sections[0].Bottom+b[1].Sections[0].Top)/2,loadZ=p.Kind==6||p.Kind==9?(r.Engineering.ConeDistance-p.Thickness/2)*Math.Cos(id=="IN"?r.Engineering.Cone1:r.Engineering.Cone2):0;var values=BearingReactions(id=="IN"?inputF:outputF,loadZ,z1,z2);r.Metric("Радиальные реакции "+id+" (оценка)",Engine.F(values[0])+" / "+Engine.F(values[1])+" Н");}r.Notes.Add("Опоры: балочная статическая оценка в одной плоскости по фактическим z-координатам опор; отрицательная реакция означает смену направления. Не учтены натяг, преднатяг, жёсткость, распределение нескольких зацеплений, внешние силы на валу и ресурс подшипника.");}
 }
}
